// Package randtoken generates cryptographically random, hex-encoded tokens.
package randtoken

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
)

// Generate returns a hex-encoded random token built from n random bytes.
func Generate(n int) (string, error) {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

// Hash returns a hex-encoded SHA-256 digest of raw, for storing tokens
// generated by Generate without keeping the raw secret at rest.
func Hash(raw string) string {
	h := sha256.Sum256([]byte(raw))
	return hex.EncodeToString(h[:])
}
